set -eu
if ! id infraset-nodejs >/dev/null 2>&1; then
  sudo -n useradd --system --user-group --home-dir /opt/infraset-nodejs --shell /usr/sbin/nologin infraset-nodejs
fi
sudo -n install -d -o infraset-nodejs -g infraset-nodejs -m 0755 /opt/infraset-nodejs
sudo -n tee /opt/infraset-nodejs/server.js >/dev/null <<'ANTRIEB_NODEJS_EOF'
'use strict';

var http = require('http');

http.createServer(function (request, response) {
  var path = request.url.split('?')[0];
  if (path === '/') {
    response.statusCode = 200;
    response.setHeader('Content-Type', 'text/plain');
    response.end('infraset-nodejs');
    return;
  }

  response.statusCode = 404;
  response.setHeader('Content-Type', 'text/plain');
  response.end('Not Found');
}).listen(3000, '127.0.0.1');
ANTRIEB_NODEJS_EOF
